(function(){
const M = window.MAC = window.MAC || {};
M.KEY_SAMPLES = { sr: 44100, credit: 'key sounds: topre switches from kbsim by Thomas Lai (github.com/tplai/kbsim), MIT',
  normal: { d: ['', '', '', '', ''], u: [''] },
  space: { d: [''], u: [''] },
  enter: { d: [''], u: [''] },
  backspace: { d: [''], u: [''] } };
M.TERM = M.TERM || { cmds: {}, apps: {} };
M.TERM.cmds.credits = { desc: 'who made what', usage: 'credits', run(argv, io){
  io.out('three.js by mrdoob and contributors, MIT\n');
  io.out(M.KEY_SAMPLES.credit + '\n', 'dim');
  io.out('everything else: kaiav\n');
} };
})();
